add_action( 'woocommerce_before_cart', 'perfectpixel_message_for_top_customers' );

function perfectpixel_message_for_top_customers() {
	$user_id = get_current_user_id();
	if ( ! $user_id ) {
		return;
	}
	if ( (float) wc_get_customer_total_spent( $user_id ) >= (float) '{{top_customer_amount}}' ) {
		echo '<div class="woocommerce-info perfectpixel-top-customer">' . wp_kses_post( '{{top_customer_message}}' ) . '</div>';
	}
}
